(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-872":{scenario:{company:"Trường Đại học Kim Ngân Hà",supervisor:{name:"Mạc Hữu Phong",role:{vi:"Giám đốc Trung tâm Khảo thí và Đảm bảo chất lượng",en:"Director of Testing & Quality Assurance"}},ref_code:"QA-8840",title:{vi:"Đúng thống kê. Đúng quyết định. Đúng minh chứng.",en:"Right statistics. Right decision. Right evidence."},brief:{vi:"Bạn rà soát báo cáo phân tích câu hỏi QA-8840 của đề thi kết thúc học phần có 200 thí sinh. Nhóm cao và nhóm thấp mỗi nhóm lấy 27% thí sinh, tức 54 người. Câu 14: nhóm cao có 41 người làm đúng, nhóm thấp có 20 người. Câu 27 có độ phân biệt âm (-0,12). Đối chiếu bản báo cáo nháp với quy trình phân tích đề thi đã duyệt, sửa quyết định xử lý câu 27 và độ phân biệt D của câu 14, rồi lập báo cáo có căn cứ.",en:"You are reviewing item analysis report QA-8840 for a final course exam taken by 200 candidates. The upper and lower groups each take 27% of candidates, that is 54 people. Item 14: 41 people in the upper group and 20 in the lower group answered correctly. Item 27 has a negative discrimination index (-0.12). Compare the draft report with the approved exam analysis procedure, correct the decision for item 27 and the discrimination index D of item 14, then write an evidence-based report."},reference_title:{vi:"Quy trình phân tích câu hỏi thi đã duyệt · QA-8840",en:"Approved item analysis procedure · QA-8840"},fields:[{id:"ITEM27_ACT",label:{vi:"Quyết định xử lý câu 27",en:"Decision for item 27"},initial:"KEEP",expected:"EXCLUDE",choices:["KEEP","REVISE","EXCLUDE"],reference:"Bảng quyết định theo độ phân biệt",hint:{vi:"Độ phân biệt âm nghĩa là nhóm thấp làm đúng nhiều hơn nhóm cao, thường do sai đáp án hoặc câu hỏi gây hiểu nhầm.",en:"A negative index means the lower group outscored the upper group, often due to a wrong key or a misleading item."}},{id:"D_ITEM14",label:{vi:"Độ phân biệt D của câu 14",en:"Discrimination index D of item 14"},initial:"0.19",expected:"0.39",reference:"Bảng thống kê câu hỏi",ref_value:{vi:"Mỗi nhóm 54 thí sinh; câu 14: nhóm cao đúng 41, nhóm thấp đúng 20",en:"54 candidates per group; item 14: upper correct 41, lower correct 20"},hint:{vi:"Kiểm tra mẫu số: công thức dùng số thí sinh của một nhóm, không phải tổng hai nhóm.",en:"Check the denominator: the formula uses one group's size, not both groups combined."}}],sop32:{vi:"D = (số đúng nhóm cao - số đúng nhóm thấp) / số thí sinh của một nhóm, làm tròn 2 chữ số thập phân. D từ 0,30: giữ; 0,20-0,29: sửa; dưới 0,20 hoặc âm: loại khỏi tính điểm và rà soát đáp án.",en:"D = (upper group correct - lower group correct) / size of one group, rounded to 2 decimals. D of 0.30 or more: keep; 0.20-0.29: revise; below 0.20 or negative: exclude from scoring and review the key."},context:{label:"PHẦN MỀM PHÂN TÍCH ĐỀ / QA-8840",metrics:[{label:{vi:"Số thí sinh",en:"Candidates"},value:"200"},{label:{vi:"Cỡ mỗi nhóm (27%)",en:"Group size (27%)"},value:"54"},{label:{vi:"D câu 27",en:"Item 27 D"},value:"-0.12"}]},crisis:{vi:"Phòng Đào tạo nhắn: “Sắp đánh giá ngoài rồi. Em soạn giúp biên bản họp rà soát đề thi cho 3 học kỳ trước, dù thực tế chưa họp, ghi lùi ngày và xin chữ ký bổ sung là được.”",en:"The Academic Affairs office writes: “External assessment is coming. Please draft exam review meeting minutes for the past 3 semesters, even though no meetings were held, backdate them and collect signatures afterwards.”"},options:{safe:{vi:"Từ chối lập minh chứng khống, báo Giám đốc Trung tâm; ghi nhận trung thực điểm còn thiếu trong báo cáo tự đánh giá, tổ chức họp rà soát thật ngay và lập kế hoạch cải tiến có thời hạn.",en:"Refuse to fabricate evidence and inform the Center Director; record the gap honestly in the self-assessment report, hold a real review meeting now and set a time-bound improvement plan."},shortcut:{vi:"Soạn biên bản lùi ngày cho kịp đoàn đánh giá, sau này sẽ họp bù cho đủ thủ tục.",en:"Draft backdated minutes for the assessors and hold catch-up meetings later to complete the formalities."},wait:{vi:"Im lặng, không soạn cũng không báo cáo, chờ đoàn đánh giá tự phát hiện.",en:"Stay silent, neither draft nor report, and wait for the assessors to notice."}},questions:{vi:["Vì sao câu 27 phải EXCLUDE và D của câu 14 là 0.39? Trình bày phép tính và bảng quyết định.","Lập minh chứng khống cho kiểm định gây hậu quả gì? Bạn xử lý điểm còn thiếu trong hệ thống đảm bảo chất lượng thế nào?"],en:["Why must item 27 be EXCLUDE and why is item 14's D equal to 0.39? Show the calculation and decision table.","What are the consequences of fabricating accreditation evidence? How do you handle the gap in the quality system?"]},hints:{vi:["Đặt báo cáo nháp cạnh bảng quyết định và kiểm tra dấu của độ phân biệt từng câu.","Áp dụng SOP mục 3.2: chia hiệu số đúng của hai nhóm cho cỡ của MỘT nhóm.","Đọc lại SOP mục 4.2: minh chứng kiểm định phải phản ánh hoạt động có thật; thiếu sót được báo cáo và đưa vào kế hoạch cải tiến."],en:["Place the draft report next to the decision table and check the sign of each item's index.","Apply SOP 3.2: divide the difference in correct answers by the size of ONE group.","Re-read SOP 4.2: accreditation evidence must reflect real activities; gaps are reported and put into an improvement plan."]}},learning:{summary:{vi:"Chuyên viên khảo thí và đảm bảo chất lượng giáo dục xây dựng ngân hàng câu hỏi, ma trận đề, tổ chức thi, phân tích thống kê câu hỏi và độ tin cậy, đồng thời vận hành hệ thống đảm bảo chất lượng bên trong và chuẩn bị tự đánh giá, đánh giá ngoài. Nghề đòi hỏi nền tảng đo lường giáo dục, thống kê, hiểu khung kiểm định và sự liêm chính tuyệt đối với dữ liệu, minh chứng.",en:"An assessment and education quality assurance specialist builds item banks and test blueprints, runs exams, analyzes item statistics and reliability, operates the internal quality assurance system and prepares self-assessment and external review. The role requires a foundation in educational measurement, statistics, knowledge of accreditation frameworks and absolute integrity with data and evidence."},responsibilities:{vi:["Xây dựng ma trận đề, bảng đặc tả liên kết chuẩn đầu ra với câu hỏi thi.","Quản lý ngân hàng câu hỏi, tổ chức thẩm định, thử nghiệm và hiệu chỉnh câu hỏi.","Phân tích độ khó, độ phân biệt, độ tin cậy sau mỗi kỳ thi và đề xuất xử lý câu hỏi.","Vận hành quy trình đảm bảo chất lượng bên trong, khảo sát các bên liên quan và theo dõi cải tiến.","Chuẩn bị báo cáo tự đánh giá, quản lý minh chứng và làm việc với đoàn đánh giá ngoài."],en:["Build test blueprints and specification tables linking learning outcomes to items.","Manage the item bank and organize item review, piloting and calibration.","Analyze difficulty, discrimination and reliability after each exam and propose item actions.","Run internal quality assurance processes, stakeholder surveys and improvement tracking.","Prepare self-assessment reports, manage evidence and work with external review panels."]},competencies:[{name:{vi:"Đo lường & đánh giá giáo dục",en:"Educational measurement"},desc:{vi:"Thiết kế đề thi giá trị, tin cậy, công bằng và khớp chuẩn đầu ra.",en:"Design valid, reliable, fair tests aligned with learning outcomes."}},{name:{vi:"Phân tích thống kê câu hỏi",en:"Item statistics analysis"},desc:{vi:"Tính và diễn giải độ khó, độ phân biệt, Cronbach's alpha và tham số IRT.",en:"Compute and interpret difficulty, discrimination, Cronbach's alpha and IRT parameters."}},{name:{vi:"Hiểu khung kiểm định",en:"Accreditation frameworks"},desc:{vi:"Nắm tiêu chuẩn, tiêu chí kiểm định trong nước và AUN-QA, liên kết minh chứng đúng tiêu chí.",en:"Know national standards and AUN-QA criteria and map evidence to the right criterion."}},{name:{vi:"Cải tiến liên tục",en:"Continuous improvement"},desc:{vi:"Vận dụng chu trình PDCA, theo dõi kế hoạch cải tiến và báo cáo tiến độ.",en:"Apply the PDCA cycle, track improvement plans and report progress."}},{name:{vi:"Liêm chính dữ liệu",en:"Data integrity"},desc:{vi:"Bảo mật đề thi, không chỉnh điểm, không lập minh chứng khống và báo cáo trung thực.",en:"Keep exams secure, never alter scores or fabricate evidence and report honestly."}}],knowledge:{vi:["Luật Giáo dục đại học số 08/2012/QH13, sửa đổi bởi Luật số 34/2018/QH14, về đảm bảo và kiểm định chất lượng.","Bộ tiêu chuẩn kiểm định chất lượng cơ sở giáo dục và chương trình đào tạo do Bộ GD&ĐT ban hành; khung AUN-QA của mạng lưới đại học ASEAN.","Lý thuyết trắc nghiệm cổ điển: độ khó p, độ phân biệt D, tương quan điểm câu - tổng và độ tin cậy Cronbach's alpha.","Lý thuyết ứng đáp câu hỏi (IRT), mô hình Rasch và cân bằng đề tương đương.","Bộ chuẩn Standards for Educational and Psychological Testing (AERA, APA, NCME, 2014) về giá trị, độ tin cậy và công bằng."],en:["Higher Education Law No. 08/2012/QH13, amended by Law No. 34/2018/QH14, on quality assurance and accreditation.","National accreditation standards for institutions and programs issued by the Ministry of Education and Training; the ASEAN University Network AUN-QA framework.","Classical test theory: difficulty p, discrimination D, item-total correlation and Cronbach's alpha reliability.","Item response theory (IRT), the Rasch model and test equating.","The Standards for Educational and Psychological Testing (AERA, APA, NCME, 2014) on validity, reliability and fairness."]},tools:["Phần mềm phân tích câu hỏi CTT và IRT","Hệ thống ngân hàng câu hỏi thi","Phần mềm thống kê","Hệ thống chấm trắc nghiệm quang học (OMR)","Phần mềm quản lý minh chứng kiểm định","Công cụ khảo sát trực tuyến"],kpis:{vi:["Tỷ lệ câu hỏi trong ngân hàng đạt độ phân biệt từ 0,30.","Độ tin cậy Cronbach's alpha của đề thi (mục tiêu mô phỏng từ 0,80).","Tỷ lệ kế hoạch cải tiến hoàn thành đúng hạn.","Số sự cố lộ đề, sai sót điểm và minh chứng không xác thực (mục tiêu bằng 0)."],en:["Share of bank items with discrimination of 0.30 or more.","Exam Cronbach's alpha reliability (training target 0.80 or more).","Share of improvement actions completed on time.","Exam leaks, scoring errors and non-genuine evidence (target zero)."]},day:[{time:"08:00",vi:"Nhận dữ liệu chấm thi, kiểm tra tính toàn vẹn tệp điểm và nhật ký truy cập.",en:"Receive scoring data and check score file integrity and access logs."},{time:"09:30",vi:"Chạy phân tích câu hỏi, đánh dấu câu có độ phân biệt thấp hoặc âm.",en:"Run item analysis and flag items with low or negative discrimination."},{time:"13:30",vi:"Họp với giảng viên ra đề, rà soát đáp án và thống nhất xử lý từng câu.",en:"Meet item writers, review keys and agree on actions for each item."},{time:"15:30",vi:"Cập nhật minh chứng, đối chiếu tiêu chí và tiến độ kế hoạch cải tiến.",en:"Update evidence, map it to criteria and track improvement plan progress."},{time:"17:00",vi:"Hoàn thiện báo cáo chất lượng đề thi gửi Hội đồng đảm bảo chất lượng.",en:"Finalize the exam quality report for the quality assurance council."}],mistakes:{vi:["Chia hiệu số đúng cho tổng hai nhóm thay vì cỡ một nhóm, làm độ phân biệt thấp đi một nửa.","Giữ câu có độ phân biệt âm mà không rà soát đáp án, gây thiệt thòi cho thí sinh giỏi.","Lập biên bản, minh chứng lùi ngày để đối phó kiểm định, làm sai lệch hệ thống chất lượng."],en:["Dividing by both groups combined instead of one group, halving the discrimination index.","Keeping a negatively discriminating item without checking the key, penalizing strong candidates.","Backdating minutes or evidence for accreditation, corrupting the quality system."]},career:[{vi:"Chuyên viên khảo thí",en:"Assessment officer"},{vi:"Chuyên viên đo lường & đảm bảo chất lượng",en:"Measurement & QA specialist"},{vi:"Trưởng phòng khảo thí & kiểm định",en:"Head of testing & accreditation"},{vi:"Giám đốc trung tâm khảo thí và đảm bảo chất lượng",en:"Director of testing & quality assurance"}],glossary:[{term:"Item difficulty (p)",vi:"Độ khó: tỷ lệ thí sinh trả lời đúng câu hỏi, p càng cao câu càng dễ.",en:"Share of candidates answering an item correctly; a higher p means an easier item."},{term:"Discrimination index (D)",vi:"Độ phân biệt: mức câu hỏi phân biệt được thí sinh giỏi và kém, tính từ nhóm cao và nhóm thấp.",en:"How well an item separates strong and weak candidates, computed from upper and lower groups."},{term:"Cronbach's alpha",vi:"Hệ số đo độ nhất quán nội tại, phản ánh độ tin cậy của bài thi.",en:"A coefficient of internal consistency reflecting test reliability."},{term:"Test blueprint",vi:"Ma trận đề, bảng đặc tả phân bố câu hỏi theo nội dung, chuẩn đầu ra và mức nhận thức.",en:"A table distributing items by content, learning outcome and cognitive level."},{term:"Self-assessment report",vi:"Báo cáo tự đánh giá của cơ sở hoặc chương trình theo bộ tiêu chuẩn trước đánh giá ngoài.",en:"An institution or program's report against standards prepared before external review."}],quiz:[{q:{vi:"Mỗi nhóm có 40 thí sinh; nhóm cao 30 người đúng, nhóm thấp 14 người đúng. Độ phân biệt D là bao nhiêu?",en:"Each group has 40 candidates; 30 in the upper group and 14 in the lower group answered correctly. What is D?"},options:{vi:["0,20","0,40","0,55","0,80"],en:["0.20","0.40","0.55","0.80"]},answer:1,explain:{vi:"D = (30 - 14) / 40 = 0,40, câu hỏi phân biệt rất tốt.",en:"D = (30 - 14) / 40 = 0.40, a very good discriminating item."}},{q:{vi:"Câu hỏi có độ khó p = 0,85 nghĩa là gì?",en:"What does an item difficulty of p = 0.85 mean?"},options:{vi:["Câu rất khó","85% thí sinh làm sai","Câu phân biệt tốt","85% thí sinh làm đúng, câu tương đối dễ"],en:["A very hard item","85% answered wrongly","A well-discriminating item","85% answered correctly, a fairly easy item"]},answer:3,explain:{vi:"Độ khó p là tỷ lệ trả lời đúng; p = 0,85 cho thấy câu dễ với nhóm thí sinh này.",en:"Difficulty p is the share answering correctly; p = 0.85 shows an easy item for this group."}},{q:{vi:"Được yêu cầu soạn biên bản họp lùi ngày để có minh chứng kiểm định. Bạn làm gì?",en:"You are asked to draft backdated meeting minutes as accreditation evidence. What do you do?"},options:{vi:["Từ chối, báo cáo và ghi nhận trung thực điểm thiếu kèm kế hoạch cải tiến","Soạn vì ai cũng làm vậy","Soạn nhưng không ký tên","Chờ đoàn đánh giá tự phát hiện"],en:["Refuse, escalate and record the gap honestly with an improvement plan","Draft them since everyone does","Draft them but do not sign","Wait for the assessors to notice"]},answer:0,explain:{vi:"Minh chứng khống làm mất giá trị kiểm định; cách đúng là minh bạch điểm yếu và cải tiến thật.",en:"Fabricated evidence voids accreditation; the right way is transparency about weaknesses and real improvement."}},{q:{vi:"Hệ số Cronbach's alpha dùng để đánh giá điều gì?",en:"What does Cronbach's alpha evaluate?"},options:{vi:["Độ khó trung bình của đề","Tỷ lệ thí sinh đạt","Độ nhất quán nội tại, tức độ tin cậy của bài thi","Thời gian làm bài"],en:["Average test difficulty","Pass rate","Internal consistency, that is test reliability","Time on test"]},answer:2,explain:{vi:"Alpha phản ánh mức các câu hỏi cùng đo một năng lực một cách nhất quán.",en:"Alpha reflects how consistently the items measure the same construct."}}],tools_en:["CTT and IRT item analysis software","Exam item bank system","Statistical software","Optical mark recognition (OMR) system","Accreditation evidence management software","Online survey tool"]}}})})(window.KKR);
